def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0] if coins[0][0] >= 0 else 0

    for i in range(m):
        for j in range(n):
            for k in range(3):  # k is the number of neutralizations used
                if i == 0 and j == 0:
                    continue
                gain = coins[i][j]
                if gain < 0:
                    gain = 0  # For negative coins, we'll determine what to do below
                # Calculate maximum with the current point considered
                if i > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k] + gain)
                if j > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k] + gain)
                # Handle the case if the current cell is a robber
                if coins[i][j] < 0:
                    if k > 0:
                        # We're using a neutralization
                        dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k - 1])
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k - 1])
                    else:
                        # We cannot neutralize
                        if i > 0:
                            dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k] - abs(coins[i][j]))
                        if j > 0:
                            dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k] - abs(coins[i][j]))
                else:
                    # If gain is positive, add it normally
                    dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k] + gain)
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k] + gain)

    return max(dp[m - 1][n - 1])

