def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    for event in sorted(events, key=lambda x: int(x[1])):
        event_type, timestamp, arg = event
        timestamp = int(timestamp)

        # Update online status for users before handling message
        for i in range(numberOfUsers):
            if not online_status[i] and offline_until[i] <= timestamp:
                online_status[i] = True

        if event_type == "OFFLINE":
            user_id = int(arg[2:])
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60
        elif event_type == "MESSAGE":
            if arg == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif arg == "HERE":
                for i in range(numberOfUsers):
                    if online_status[i]:
                        mentions[i] += 1
            else:
                mentioned_ids = arg.split()
                for mentioned_id in mentioned_ids:
                    user_id = int(mentioned_id[2:])
                    mentions[user_id] += 1

    return mentions

def maxDistance(s: str, k: int) -> int:
    # Initialize the starting position at the origin
    x, y = 0, 0
    max_distance = 0

    # Move according to the instructions in the string s
    for move in s:
        if move == 'N':
            y += 1
        elif move == 'S':
            y -= 1
        elif move == 'E':
            x += 1
        elif move == 'W':
            x -= 1

        # Calculate the current Manhattan distance
        current_distance = abs(x) + abs(y)
        # Update the maximum distance
        max_distance = max(max_distance, current_distance)

    # Calculate the maximum possible distance considering k changes
    return max_distance + min(k, max_distance)
